3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Events;
6	
7	use App\Enums\UserRole;
8	use App\Models\Team;
9	use App\Models\User;
10	use App\Modules\Events\Enums\EventState;
11	use App\Modules\Events\Models\Event;
12	use DOMDocument;
13	use DOMElement;
14	use DOMXPath;
15	use Illuminate\Support\Facades\Cache;
16	use PHPUnit\Framework\Attributes\Group;
17	use PHPUnit\Framework\Attributes\Test;
18	use Tests\Feature\FeatureTestCase;
19	
20	/**
21	 * Capsule T2 ATDD — shared event page shell adopted by a new page (Event
22	 * Overview) and an existing one (Landing Preview).
23	 *
24	 * Assertions are on the rendered contract (which regions exist and where they
25	 * are nested), the HTTP outcome, and refusals — never on which Blade file
26	 * produced the markup.
27	 */
28	#[Group('events')]
29	class EventPageShellAdoptionTest extends FeatureTestCase
30	{
31	    protected function setUp(): void
32	    {
33	        parent::setUp();
34	
35	        // PermissionCacheService keys on user_id + team_id and RefreshDatabase
36	        // recycles ids across tests.
37	        Cache::flush();
38	    }
39	
40	    /**
41	     * @return array{0: User, 1: Team, 2: Event}
42	     */
43	    private function adminWithEvent(bool $cancelled = false): array
44	    {
45	        $admin = User::factory()->create();
46	        $team = Team::factory()->create(['user_id' => $admin->id]);
47	        $admin->teams()->attach($team, ['role' => UserRole::ADMIN->value]);
48	        $admin->forceFill(['current_team_id' => $team->id])->save();
49	
50	        $factory = Event::factory()->inState(EventState::DRAFT)->for($team);
51	
52	        if ($cancelled) {
53	            $factory = $factory->cancelled();
54	        }
55	
56	        $event = $factory->create(['created_by' => $admin->id]);
57	
58	        return [$admin->fresh(), $team->fresh(), $event->fresh()];
59	    }
60	
61	    private function xpath(string $html): DOMXPath
62	    {
63	        $document = new DOMDocument();
64	        $previous = libxml_use_internal_errors(true);
65	        $document->loadHTML('<?xml encoding="utf-8" ?>'.$html);
66	        libxml_clear_errors();
67	        libxml_use_internal_errors($previous);
68	
69	        return new DOMXPath($document);
70	    }
71	
72	    private function element(DOMXPath $xpath, string $testId): ?DOMElement
73	    {
74	        $found = $xpath->query(sprintf('//*[@data-testid="%s"]', $testId));
75	
76	        return $found !== false && $found->length > 0 && $found->item(0) instanceof DOMElement
77	            ? $found->item(0)
78	            : null;
79	    }
80	
81	    /**
82	     * The shared shell contract: one root region that itself renders the page
83	     * title, the event settings tab strip, and an actions region.
84	     */
85	    private function assertRendersThroughSharedShell(string $html, string $context): void
86	    {
87	        $xpath = $this->xpath($html);
88	        $shell = $this->element($xpath, 'event-page-shell');
89	
90	        $this->assertNotNull($shell, $context.': shared event page shell is missing');
91	
92	        foreach (['event-page-shell-title', 'event-settings-tabs', 'event-page-shell-actions'] as $region) {
93	            $nested = $xpath->query(sprintf('.//*[@data-testid="%s"]', $region), $shell);
94	
95	            $this->assertTrue(
96	                $nested !== false && $nested->length > 0,
97	                $context.': shared shell does not render the "'.$region.'" region',
98	            );
99	        }
100	    }
101	
102	    #[Test]
103	    public function event_overview_page_is_reachable_and_renders_through_the_shared_shell(): void
104	    {
105	        [$admin, , $event] = $this->adminWithEvent();
106	
107	        $this->assertSame(
108	            '/events/'.$event->uuid.'/overview',
109	            parse_url(route('events.overview', $event), PHP_URL_PATH),
110	        );
111	
112	        $response = $this->actingAs($admin)->get(route('events.overview', $event));
113	
114	        $response->assertOk();
115	        $response->assertSee('data-testid="event-overview-page"', false);
116	
117	        $this->assertRendersThroughSharedShell($response->getContent(), 'events.overview');
118	    }
119	
120	    #[Test]
121	    public function landing_preview_renders_through_the_same_shell_without_losing_its_behaviour(): void
122	    {
123	        [$admin, , $event] = $this->adminWithEvent();
124	
125	        $response = $this->actingAs($admin)->get(route('events.landing.preview', $event));
126	
127	        $response->assertOk();
128	
129	        $this->assertRendersThroughSharedShell($response->getContent(), 'events.landing.preview');
130	
131	        // Behaviour other pages/tests already depend on must survive the retrofit.
132	        $response->assertSee('data-testid="landing-preview-page"', false);
133	        $response->assertSee('data-testid="landing-preview-page-menu"', false);
134	        $response->assertSee('data-testid="landing-preview-edit-action"', false);
135	        $response->assertSee('data-testid="landing-preview-publish-action"', false);
136	    }
137	
138	    #[Test]
139	    public function shell_action_visibility_follows_the_shared_event_action_model(): void
140	    {
141	        // A cancelled event drives manageLanding.visible => false in
