44	+     * @param  array<int, string>  $except
45	+     */
46	+    public static function currentItemIndex(array $items, array $except = []): int|string|null
47	+    {
48	+        foreach ($items as $index => $item) {
49	+            if (empty($item['route'])) {
50	+                continue;
51	+            }
52	+
53	+            if (in_array($item['key'] ?? null, $except, true)) {
54	+                continue;
55	+            }
56	+
57	+            if (($item['active'] ?? false) === true) {
58	+                return $index;
59	+            }
60	+        }
61	+
62	+        return null;
63	+    }
