65	+    /**
66	+     * Key identifying the page being rendered. Uses the current navigation
67	+     * item's key when the page is a navigation target, so the region marker and
68	+     * the link that points at it share one key space; otherwise falls back to
69	+     * the current route name.
70	+     *
71	+     * @param  array<array-key, array<string, mixed>>  $items
72	+     */
73	+    public static function forCurrentPage(array $items, ?string $routeName = null): string
74	+    {
75	+        $index = self::currentItemIndex($items);
76	+
77	+        if ($index !== null) {
78	+            return self::forItem($items[$index]);
79	+        }
80	+
81	+        return self::normalize((string) $routeName);
82	+    }
83	+
84	+    private static function normalize(string $raw): string
85	+    {
86	+        $slug = trim((string) preg_replace('/[^a-z0-9]+/', '-', mb_strtolower($raw)), '-');
87	+
88	+        return $slug === '' ? 'page' : $slug;
89	+    }
