301	+                ],
302	+                [
303	+                    'key' => 'tenant-events',
304	+                    'label' => 'Events',
305	+                    'route' => 'events.index',
306	+                    'data_testid' => 'nav-events',
307	+                    'active' => false,
308	+                ],
309	+                [
310	+                    'key' => 'tenant-routeless',
311	+                    'label' => 'Routeless',
312	+                    'route' => null,
313	+                ],
314	+            ],
315	+        ])->render();
316	+
317	+        $links = $this->primaryNavLinks($html, mobile: true);
318	+
319	+        // AC6 — exclusion list and route-less items still drop out; test id and
320	+        // href output is unchanged.
321	+        $this->assertSame(['nav-dashboard-mobile'], array_keys($links));
322	+        $this->assertSame(route('user.dashboard'), $links['nav-dashboard-mobile']['href'] ?? null);
323	+        $this->assertStringNotContainsString('nav-events', $html);
324	+        $this->assertStringNotContainsString('nav-tenant-routeless', $html);
325	+
326	+        // AC6 — badge still renders alongside the new contract attributes.
327	+        $this->assertMatchesRegularExpression('/<span[^>]*>\s*7\s*<\/span>/', $html);
328	+
329	+        // AC1/AC4 — the mobile-only rendering still carries both markers.
330	+        $this->assertSame('page', $links['nav-dashboard-mobile']['aria-current'] ?? null);
331	+        $this->assertNotSame('', $links['nav-dashboard-mobile'][self::SCROLL_KEY_ATTRIBUTE] ?? '');
332	+    }
333	+
334	+    private const SCROLL_KEY_ATTRIBUTE = 'data-scroll-restore-key';
335	+
336	+    /**
337	+     * Primary-navigation anchors from rendered HTML, keyed by test id.
338	+     *
339	+     * @return array<string, array<string, string>>
340	+     */
341	+    private function primaryNavLinks(string $html, bool $mobile): array
342	+    {
343	+        preg_match_all('/<a\b[^>]*>/i', $html, $tags);
344	+
345	+        $links = [];
346	+
347	+        foreach ($tags[0] as $tag) {
348	+            preg_match_all('/([a-zA-Z0-9_:.\-]+)="([^"]*)"/', $tag, $matches, PREG_SET_ORDER);
349	+
350	+            $attributes = [];
351	+
352	+            foreach ($matches as $match) {
353	+                $attributes[$match[1]] = $match[2];
354	+            }
355	+
356	+            $testid = $attributes['data-testid'] ?? '';
357	+
358	+            if (! str_starts_with($testid, 'nav-')) {
359	+                continue;
360	+            }
361	+
362	+            if (str_ends_with($testid, '-mobile') !== $mobile) {
363	+                continue;
364	+            }
365	+
366	+            $links[$testid] = $attributes;
367	+        }
368	+
369	+        return $links;
370	+    }
371	+
372	+    /**
373	+     * @param  array<string, array<string, string>>  $links
374	+     * @return array<string, array<string, string>>
375	+     */
376	+    private function currentLinks(array $links): array
377	+    {
378	+        return array_filter(
379	+            $links,
380	+            static fn (array $attributes): bool => ($attributes['aria-current'] ?? null) === 'page',
381	+        );
382	+    }
383	+}
