5	namespace Platform\UiNavigation;
6	
7	use Illuminate\Http\Request;
8	
9	/**
10	 * Resolves active state for navigation items based on the current request route.
11	 *
12	 * Stateless — instantiate with a Request or resolve from the container.
13	 */
14	class ActiveStateResolver
15	{
16	    public function __construct(
17	        private readonly Request $request,
18	    ) {}
19	
20	    /**
21	     * Check if a route is currently active.
22	     * Matches the exact route or any route under its prefix (e.g. show, edit, create).
23	     */
24	    public function isRouteActive(string $route, bool $exact = false): bool
25	    {
26	        $currentRoute = $this->request->route()?->getName();
27	
28	        if (! $currentRoute) {
29	            return false;
30	        }
31	
32	        $isExactMatch = $currentRoute === $route;
33	
34	        if ($exact || $isExactMatch) {
35	            return $isExactMatch;
36	        }
37	
38	        // Derive the route prefix by stripping the terminal action segment
39	        // e.g. "admin.tickets.index" → "admin.tickets"
40	        // Any route under that prefix (show, edit, create, …) is considered active.
41	        $prefix = preg_replace('/\.(index|show|create|edit|store|update|destroy)$/', '', $route);
42	
43	        return str_starts_with($currentRoute, "{$prefix}.");
44	    }
45	
46	    /**
47	     * Update active states in a cached menu structure.
48	     *
49	     * Menu items must carry a `_key` field (set during build) so
50	     * we can recalculate without re-reading config.
51	     *
52	     * @param  array<int, array<string, mixed>>  $menu
53	     * @return array<int, array<string, mixed>>
54	     */
55	    public function updateActiveStates(array $menu): array
56	    {
57	        foreach ($menu as $index => $item) {
58	            if (($item['type'] ?? null) === 'section' && isset($item['items'])) {
59	                $sectionActive = false;
60	
61	                foreach ($item['items'] as $childIndex => $child) {
62	                    if (isset($child['route'])) {
63	                        $active = $this->isRouteActive($child['route'], (bool) ($child['active_exact'] ?? false));
64	                        $menu[$index]['items'][$childIndex]['active'] = $active;
65	                        if ($active) {
66	                            $sectionActive = true;
67	                        }
68	                    }
69	                }
70	
71	                $menu[$index]['active'] = $sectionActive;
72	            } elseif (isset($item['route'])) {
73	                $menu[$index]['active'] = $this->isRouteActive($item['route'], (bool) ($item['active_exact'] ?? false));
74	            }
75	        }
76	
77	        return $menu;
78	    }
79	}
