9	+declare(strict_types=1);
10	+
11	+namespace App\Navigation;
12	+
13	+use Illuminate\Http\Request;
14	+
15	+/**
16	+ * Server-rendered half of the scroll-restoration contract.
17	+ *
18	+ * The front end remembers the offset of the region it is leaving
19	+ * (`data-scroll-region`) and restores it when the same page is rendered again
20	+ * on Back/Forward. Primary nav links carry the key of the item they belong to
21	+ * (`data-scroll-key`) so that bookkeeping does not depend on which rendering
22	+ * variant — desktop bar or mobile drawer — the user actually clicked.
23	+ *
24	+ * Both keys are pure functions of what they describe: the same item, and the
25	+ * same page, always produce the same string.
26	+ */
27	+final class ScrollRestoration
28	+{
29	+    /**
30	+     * Key for a navigation item, identical in every rendering variant.
31	+     *
32	+     * Derived only from identifiers that do not move between requests — never
33	+     * from the label, which is translated and would change with the locale.
34	+     *
35	+     * @param  array<string, mixed>  $item
36	+     */
37	+    public static function itemKey(array $item): string
38	+    {
39	+        $source = $item['key'] ?? $item['route'] ?? $item['data_testid'] ?? null;
40	+
41	+        return 'nav:' . (self::normalize((string) $source) ?: 'unknown');
42	+    }
43	+
44	+    /**
45	+     * Marker for the page currently being rendered.
46	+     *
47	+     * Route parameters are part of the page identity (/events/1 and /events/2
48	+     * are different pages); the query string is not, so one page keeps a single
49	+     * offset across filter and sort changes.
50	+     */
51	+    public static function regionKey(?Request $request = null): string
52	+    {
53	+        $request ??= request();
54	+        $route = $request?->route();
55	+        $name = $route?->getName();
56	+
57	+        if ($name === null || $name === '') {
58	+            return 'page:' . (self::normalize(trim((string) $request?->path(), '/')) ?: 'root');
59	+        }
60	+
61	+        $parameters = array_map(
62	+            static fn ($value): string => self::normalize((string) $value),
63	+            array_values(array_filter($route->originalParameters(), 'is_scalar')),
64	+        );
65	+
66	+        return 'page:' . implode(':', [self::normalize($name), ...$parameters]);
67	+    }
68	+
69	+    /**
70	+     * Reduce a raw identifier to characters that are safe and predictable in an
71	+     * HTML attribute and in client-side storage keys.
72	+     */
73	+    private static function normalize(string $value): string
74	+    {
75	+        return trim((string) preg_replace('/[^A-Za-z0-9._\/-]+/', '-', $value), '-');
76	+    }
77	+}
