139	+<?php
140	+
141	+declare(strict_types=1);
142	+
143	+namespace App\Modules\SuperAdmin\Services;
144	+
145	+use App\Models\User;
146	+use App\Modules\Events\Models\Event;
147	+use App\Modules\Events\Models\Registration;
148	+use App\Modules\SuperAdmin\Contracts\Repositories\SuperAdminEventRepositoryInterface;
149	+use Illuminate\Auth\Access\AuthorizationException;
150	+use Illuminate\Support\Facades\Gate;
151	+use Symfony\Component\HttpFoundation\StreamedResponse;
152	+
153	+/**
154	+ * Capsule T4 — platform-admin export of a single event's registration list.
155	+ *
156	+ * Support staff pull this list when investigating a delivery complaint, so the
157	+ * rows carry attendee personal data. Two consequences shape this service:
158	+ *
159	+ *   1. Authorization is explicit and narrow. The capability checked here is the
160	+ *      same `events.view.global` mapped to `admin.events.registrations.export`
161	+ *      in config/route_permissions.php — reaching the admin area is not enough.
162	+ *      The re-check is deliberate defence in depth: the route middleware is the
163	+ *      first gate, this guard is the one that travels with the data.
164	+ *   2. The query is bound to the requested event only, never to whatever the
165	+ *      actor's TeamScope bypass would otherwise expose.
166	+ */
167	+class SuperAdminEventRegistrationExportService
168	+{
169	+    /**
170	+     * The single capability that unlocks attendee personal data platform-wide.
171	+     * Keep identical to the `admin.events.registrations.export` entry in
172	+     * config/route_permissions.php.
173	+     */
174	+    public const CAPABILITY = 'events.view.global';
175	+
176	+    public function __construct(
177	+        private readonly SuperAdminEventRepositoryInterface $events,
178	+    ) {}
179	+
180	+    /**
181	+     * @throws AuthorizationException
182	+     */
183	+    public function response(Event $event, User $actor): StreamedResponse
184	+    {
185	+        $this->authorize($actor);
186	+
187	+        $rows = $this->rows($event);
188	+
189	+        return response()->streamDownload(function () use ($rows): void {
190	+            $handle = fopen('php://output', 'wb');
191	+            if ($handle === false) {
192	+                return;
193	+            }
194	+
195	+            foreach ($rows as $row) {
196	+                fputcsv($handle, $row, escape: '\\');
197	+            }
198	+
199	+            fclose($handle);
200	+        }, $this->filename($event), [
201	+            'Content-Type' => 'text/csv; charset=UTF-8',
202	+        ]);
203	+    }
204	+
205	+    /**
206	+     * @throws AuthorizationException
207	+     */
208	+    private function authorize(User $actor): void
209	+    {
210	+        if (! Gate::forUser($actor)->allows(self::CAPABILITY)) {
211	+            throw new AuthorizationException(
212	+                'Exporting an event registration list requires '.self::CAPABILITY.'.'
213	+            );
214	+        }
215	+    }
216	+
217	+    /**
218	+     * Header row plus one row per registration of this event.
219	+     *
220	+     * @return list<list<string>>
221	+     */
222	+    private function rows(Event $event): array
223	+    {
224	+        $rows = [$this->headers()];
225	+
226	+        foreach ($this->events->registrationsForEvent($event) as $index => $registration) {
227	+            /** @var Registration $registration */
228	+            $rows[] = [
229	+                (string) ($index + 1),
230	+                (string) $registration->full_name,
231	+                (string) $registration->email,
232	+                (string) $registration->source,
233	+                $registration->created_at->toIso8601String(),
234	+                $registration->confirmation_sent_at?->toIso8601String() ?? '',
235	+                $registration->last_confirmation_sent_at?->toIso8601String() ?? '',
236	+                $registration->attended_at?->toIso8601String() ?? '',
237	+            ];
238	+        }
239	+
240	+        return $rows;
241	+    }
242	+
243	+    /**
244	+     * @return list<string>
245	+     */
246	+    private function headers(): array
247	+    {
248	+        $headers = __('super-admin::super-admin.registration_export.headers');
249	+
250	+        return is_array($headers) ? array_values(array_map('strval', $headers)) : [];
251	+    }
252	+
253	+    /**
254	+     * The uuid keeps the download traceable to the exact event it was pulled
255	+     * for — the title alone is neither unique nor stable across workspaces.
256	+     */
257	+    private function filename(Event $event): string
258	+    {
259	+        return sprintf('event-%s-registrations.csv', $event->uuid);
260	+    }
261	+}
