351	+
352	+/**
353	+ * Capsule T4 — platform-admin export of a single event's registration list.
354	+ *
355	+ * The rows carry attendee personal data, so the endpoint must be gated by the
356	+ * same global capability that already governs platform-wide event visibility
357	+ * (events.view.global) rather than by generic admin-area membership.
358	+ */
359	+class AdminEventRegistrationExportTest extends FeatureTestCase
360	+{
361	+    use InteractsWithSuperAdmin;
362	+
363	+    private const EXPORT_ROUTE = 'admin.events.registrations.export';
364	+
365	+    // -------------------------------------------------------------------------
366	+    // AC1 / AC4 / AC5 — CSV download scoped to the requested event
367	+    // -------------------------------------------------------------------------
368	+
369	+    #[Test]
370	+    #[TestDox('T4-EXPORT-01 [P0] Given a platform admin when they export an event then only that event\'s registrations are streamed as a CSV download')]
371	+    public function platform_admin_exports_only_the_requested_events_registrations(): void
372	+    {
373	+        $workspace = $this->createWorkspace();
374	+        $otherWorkspace = $this->createWorkspace();
375	+
376	+        $event = Event::factory()->for($workspace)->create(['title' => 'Delivery Complaint Event']);
377	+        $otherEvent = Event::factory()->for($otherWorkspace)->create(['title' => 'Unrelated Event']);
378	+
379	+        $this->registerAttendee($event, 'first.attendee@example.test');
380	+        $this->registerAttendee($event, 'second.attendee@example.test');
381	+        $this->registerAttendee($otherEvent, 'other.event.attendee@example.test');
382	+
383	+        $admin = $this->createPlatformSuperAdmin($workspace);
384	+
385	+        $response = $this->actingAs($admin)->get($this->exportUrl($event));
386	+
387	+        $response->assertOk();
388	+
389	+        // AC5 — delivered as a CSV download naming the event it belongs to.
390	+        $this->assertStringContainsString('text/csv', (string) $response->headers->get('Content-Type'));
391	+        $disposition = (string) $response->headers->get('Content-Disposition');
392	+        $this->assertStringContainsString('attachment', $disposition);
393	+        $this->assertStringContainsString($event->uuid, $disposition);
394	+
395	+        // AC4 — the requested event's registrations, and nothing from another event.
396	+        $body = $this->bodyOf($response);
397	+        $this->assertStringContainsString('first.attendee@example.test', $body);
398	+        $this->assertStringContainsString('second.attendee@example.test', $body);
399	+        $this->assertStringNotContainsString('other.event.attendee@example.test', $body);
400	+    }
401	+
402	+    // -------------------------------------------------------------------------
403	+    // AC3 — admin-area access alone does not unlock attendee personal data
404	+    // -------------------------------------------------------------------------
405	+
406	+    #[Test]
407	+    #[TestDox('T4-EXPORT-02 [P0] Given an admin-area user without global event visibility when they request the export then they are refused and receive no registration data')]
408	+    public function admin_area_user_without_global_event_visibility_is_refused(): void
409	+    {
410	+        $workspace = $this->createWorkspace();
411	+        $event = Event::factory()->for($workspace)->create(['title' => 'Delivery Complaint Event']);
412	+        $this->registerAttendee($event, 'protected.attendee@example.test');
413	+
414	+        // Reaches the admin area (system-admin flagged role) but was never
415	+        // granted the global event-visibility capability.
416	+        $role = Role::query()->create([
417	+            'name' => 'Support Desk Without Event Visibility',
418	+            'key' => 't4-support-desk-no-event-visibility',
419	+            'description' => 'Test-only system role that reaches the admin area but cannot view events platform-wide.',
420	+            'is_system_role' => false,
421	+            'is_system_admin' => true,
422	+        ]);
423	+
424	+        $supportUser = User::factory()->create([
425	+            'email_verified_at' => now(),
426	+            'current_team_id' => $workspace->id,
427	+        ]);
428	+        $workspace->users()->attach($supportUser, ['role' => $role->key]);
429	+        $supportUser = $supportUser->fresh(['currentTeam']);
430	+
431	+        // Precondition: this actor genuinely reaches the platform-admin area.
432	+        $this->actingAs($supportUser)->get(route('admin.dashboard'))->assertOk();
433	+
434	+        $response = $this->actingAs($supportUser)->get($this->exportUrl($event));
435	+
436	+        $response->assertForbidden();
437	+        $this->assertStringNotContainsString('protected.attendee@example.test', $this->bodyOf($response));
438	+    }
439	+
440	+    // -------------------------------------------------------------------------
441	+    // AC2 / AC6 — config gating agrees with the endpoint, neighbours untouched
442	+    // -------------------------------------------------------------------------
443	+
444	+    #[Test]
445	+    #[TestDox('T4-EXPORT-03 [P0] Given the route-permission config when the export route is added then it requires global event visibility and pre-existing admin event entries are unchanged')]
446	+    public function export_route_is_capability_gated_without_widening_existing_admin_routes(): void
447	+    {
448	+        /** @var array<string, string|null> $permissions */
449	+        $permissions = config('route_permissions.routes');
450	+
451	+        $this->assertSame(
452	+            'events.view.global',
453	+            $permissions[self::EXPORT_ROUTE] ?? null,
454	+            'The export route must be gated by the global event-visibility capability it enforces.',
455	+        );
456	+
457	+        // AC6 — the neighbouring admin event entries keep their original gates.
458	+        $this->assertSame('events.view.global', $permissions['admin.events.index'] ?? null);
459	+        $this->assertSame('events.view.global', $permissions['admin.events.show'] ?? null);
460	+        $this->assertSame('events.update.global', $permissions['admin.events.edit'] ?? null);
461	+        $this->assertSame('system_admin_access', $permissions['admin.dashboard'] ?? null);
462	+    }
463	+
464	+    // -------------------------------------------------------------------------
465	+    // Helpers
466	+    // -------------------------------------------------------------------------
467	+
468	+    private function exportUrl(Event $event): string
469	+    {
470	+        $this->assertTrue(
471	+            Route::has(self::EXPORT_ROUTE),
472	+            'Named route ['.self::EXPORT_ROUTE.'] does not exist.',
473	+        );
474	+
475	+        return route(self::EXPORT_ROUTE, $event->uuid);
476	+    }
477	+
478	+    private function registerAttendee(Event $event, string $email): Registration
479	+    {
480	+        return Registration::unguarded(fn (): Registration => Registration::query()->create([
481	+            'team_id' => $event->team_id,
482	+            'event_id' => $event->id,
483	+            'email' => $email,
484	+            'email_hash' => hash('sha256', $email),
485	+            'source' => 'direct',
486	+            'full_name' => 'Attendee '.substr(md5($email), 0, 6),
487	+            'consent_accepted_at' => now(),
488	+        ]));
