3	namespace App\Scopes;
4	
5	use Illuminate\Database\Eloquent\Builder;
6	use Illuminate\Database\Eloquent\Model;
7	use Illuminate\Database\Eloquent\Scope;
8	use Platform\Tenancy\Contracts\TenantContextInterface;
9	
10	class TeamScope implements Scope
11	{
12	    /**
13	     * Apply the scope to a given Eloquent query builder.
14	     *
15	     * Uses TenantContextInterface from the platform-tenancy package
16	     * to resolve the current tenant ID. Fails closed (WHERE 1=0)
17	     * when no tenant context is available.
18	     */
19	    public function apply(Builder $builder, Model $model): void
20	    {
21	        $tenantContext = app(TenantContextInterface::class);
22	
23	        // System admin bypass — skip scoping entirely
24	        if ($tenantContext->shouldBypassTenantScope()) {
25	            return;
26	        }
27	
28	        $tenantId = $tenantContext->getTenantId();
29	
30	        if ($tenantId !== null) {
31	            $builder->where(
32	                $model->getTable() . '.team_id',
33	                $tenantId
34	            );
35	        } else {
36	            // Fail closed — no tenant context means no records
37	            $builder->whereRaw('1=0');
38	        }
39	    }
40	
41	    /**
42	     * Extend the query builder with macros.
43	     *
44	     * @param Builder $builder
45	     */
46	    public function extend(Builder $builder): void
47	    {
48	        $builder->macro("withoutTeamScope", function (Builder $builder) {
49	            return $builder->withoutGlobalScope(TeamScope::class);
50	        });
51	
52	        $builder->macro("forAllTeams", function (Builder $builder) {
53	            return $builder->withoutGlobalScope(TeamScope::class);
54	        });
55	
56	        $builder->macro("forTeam", function (Builder $builder, $team) {
57	            $teamId = is_object($team) ? $team->id : $team;
58	            return $builder
59	                ->withoutGlobalScope(TeamScope::class)
60	                ->where("team_id", $teamId);
61	        });
62	
63	        $builder->macro("forCurrentTeam", function (Builder $builder) {
64	            $tenantContext = app(TenantContextInterface::class);
65	            $tenantId = $tenantContext->getTenantId();
66	
67	            if ($tenantId !== null) {
68	                return $builder
69	                    ->withoutGlobalScope(TeamScope::class)
70	                    ->where("team_id", $tenantId);
71	            }
72	            return $builder->withoutGlobalScope(TeamScope::class)->whereRaw('1=0');
73	        });
74	
75	        $builder->macro("forUserTeams", function (
76	            Builder $builder,
77	            $user = null,
78	        ) {
79	            $user = $user ?: \Illuminate\Support\Facades\Auth::user();
80	            if ($user && method_exists($user, 'teams')) {
81	                $teamIds = $user->teams()->pluck("teams.id");
82	                return $builder
83	                    ->withoutGlobalScope(TeamScope::class)
84	                    ->whereIn("team_id", $teamIds);
85	            }
86	            return $builder->withoutGlobalScope(TeamScope::class)->whereRaw('1=0');
87	        });
88	    }
89	}
