72	+<?php
73	+
74	+declare(strict_types=1);
75	+
76	+namespace App\Modules\SuperAdmin\Services;
77	+
78	+use App\Modules\Events\Models\Event;
79	+use App\Modules\Events\Models\Registration;
80	+use Illuminate\Database\Eloquent\Collection;
81	+use Symfony\Component\HttpFoundation\StreamedResponse;
82	+
83	+/**
84	+ * Platform-support export of a single event's registration list.
85	+ *
86	+ * Separate from the tenant-facing EventExportService: platform support staff
87	+ * must be able to pull the list while investigating a delivery complaint
88	+ * regardless of the workspace's plan entitlements, and the row shape carries
89	+ * the registrant email that the delivery investigation needs.
90	+ *
91	+ * TeamScope is bypassed at the scope layer for SYSTEM_ADMIN actors
92	+ * (User::shouldBypassTeamScope), so no explicit scope bypass belongs here.
93	+ */
94	+class SuperAdminRegistrationExportService
95	+{
96	+    public function response(Event $event): StreamedResponse
97	+    {
98	+        $rows = $this->rows($event);
99	+
100	+        return response()->streamDownload(function () use ($rows): void {
101	+            $handle = fopen('php://output', 'wb');
102	+            if ($handle === false) {
103	+                return;
104	+            }
105	+
106	+            foreach ($rows as $row) {
107	+                fputcsv($handle, $row, escape: '\\');
108	+            }
109	+
110	+            fclose($handle);
111	+        }, $this->filename($event), [
112	+            'Content-Type' => 'text/csv; charset=UTF-8',
113	+        ]);
114	+    }
115	+
116	+    /**
117	+     * @return list<list<string>>
118	+     */
119	+    private function rows(Event $event): array
120	+    {
121	+        $rows = [$this->headers()];
122	+
123	+        /** @var Collection<int, Registration> $registrations */
124	+        $registrations = Registration::query()
125	+            ->where('event_id', $event->id)
126	+            ->orderBy('created_at')
127	+            ->orderBy('id')
128	+            ->get();
129	+
130	+        foreach ($registrations as $index => $registration) {
131	+            $rows[] = [
132	+                (string) ($index + 1),
133	+                (string) $registration->full_name,
134	+                (string) $registration->email,
135	+                (string) ($registration->company ?? ''),
136	+                (string) ($registration->title ?? ''),
137	+                (string) ($registration->country ?? ''),
138	+                (string) ($registration->industry ?? ''),
139	+                (string) $registration->source,
140	+                $registration->attended_at?->toIso8601String() ?? '',
141	+                $registration->created_at->toIso8601String(),
142	+            ];
143	+        }
144	+
145	+        return $rows;
146	+    }
147	+
148	+    /**
149	+     * @return list<string>
150	+     */
151	+    private function headers(): array
152	+    {
153	+        $headers = __('events.exports.headers.platform_registrations');
154	+
155	+        return is_array($headers) ? array_values(array_map('strval', $headers)) : [];
156	+    }
157	+
158	+    private function filename(Event $event): string
159	+    {
160	+        $slug = str((string) $event->title)->slug('-')->toString();
161	+        $stem = $slug !== '' ? $slug : 'event';
162	+
163	+        return sprintf('%s-%s-registrations.csv', $stem, $event->uuid);
164	+    }
165	+}
