164	+ * middleware on events.public.landing-share, before anything is resolved.
165	+ */
166	+final class LandingShareLinkService
167	+{
168	+    /** Long enough for a colleague to review, short enough to lapse on its own. */
169	+    public const TTL_HOURS = 72;
170	+
171	+    public function __construct(
172	+        private readonly EventService $events,
173	+    ) {}
174	+
175	+    /**
176	+     * Mint a review link for this event's landing preview.
177	+     *
178	+     * Re-checks the event-update capability the route already gated on, so
179	+     * the link cannot be minted by an actor who may only view the event.
180	+     *
181	+     * @throws \Illuminate\Auth\Access\AuthorizationException
182	+     */
183	+    public function mintForReview(Event $event, User $actor): string
184	+    {
185	+        $this->events->authorizeLandingFormAccess($event, $actor);
186	+
187	+        return URL::temporarySignedRoute(
188	+            'events.public.landing-share',
189	+            now()->addHours(self::TTL_HOURS),
190	+            ['eventUuid' => $event->uuid],
191	+        );
192	+    }
193	+}
