283	+<?php
284	+
285	+declare(strict_types=1);
286	+
287	+namespace Tests\Feature\Events;
288	+
289	+use App\Enums\UserRole;
290	+use App\Models\Team;
291	+use App\Models\User;
292	+use App\Modules\Events\Enums\EventState;
293	+use App\Modules\Events\Models\Event;
294	+use App\Modules\Events\Models\LandingPage;
295	+use Illuminate\Support\Facades\Cache;
296	+use PHPUnit\Framework\Attributes\Group;
297	+use PHPUnit\Framework\Attributes\Test;
298	+use Tests\Feature\FeatureTestCase;
299	+
300	+/**
301	+ * Capsule T5 ATDD — Shareable landing-preview link for unauthenticated reviewers.
302	+ *
303	+ * Covers:
304	+ *  - AC1 organiser with the event-update capability mints a link via POST events.landing.share
305	+ *  - AC2 GET events.public.landing-share serves an unauthenticated read-only preview, DRAFT included
306	+ *  - AC3 tamper-evident and time-limited: altered parameters and expired links are refused
307	+ *  - AC4 a link minted for one event does not grant access to another event
308	+ *  - AC5 an actor without the event-update capability cannot mint a link
309	+ *  - AC6 the shared view carries no registration submission and no authoring control, and
310	+ *        visiting it neither authenticates the visitor nor opens the authenticated editor
311	+ *
312	+ * Contract this test pins for the implementer:
313	+ *  - POST events.landing.share responds successfully with JSON {"url": "<absolute share link>"}
314	+ *  - the minted link is event-scoped (the event uuid appears in it) and signed by the
315	+ *    framework's signed-URL mechanism, so refusals surface as HTTP 403
316	+ *  - the shared surface renders with data-testid="landing-share-preview"
317	+ *
318	+ * ALL tests intentionally FAIL on HEAD: neither route exists, so no share link can be
319	+ * minted and no unauthenticated read-only preview can be served.
320	+ */
321	+#[Group('events')]
322	+#[Group('p1')]
323	+class LandingPreviewShareLinkTest extends FeatureTestCase
324	+{
325	+    protected function setUp(): void
326	+    {
327	+        parent::setUp();
328	+        Cache::flush();
329	+    }
330	+
331	+    /**
332	+     * @return array{0: User, 1: Team, 2: Event}
333	+     */
334	+    private function organiserWithDraftEvent(string $title = 'Draft Product Ops Briefing'): array
335	+    {
336	+        $organiser = User::factory()->create();
337	+        $team = Team::factory()->create(['user_id' => $organiser->id]);
338	+        $organiser->teams()->attach($team, ['role' => UserRole::ADMIN->value]);
339	+        $organiser->forceFill(['current_team_id' => $team->id])->save();
340	+
341	+        $event = Event::factory()
342	+            ->inState(EventState::DRAFT)
343	+            ->for($team)
344	+            ->create([
345	+                'created_by' => $organiser->id,
346	+                'title' => $title,
347	+            ]);
348	+
349	+        LandingPage::factory()->for($event)->create([
350	+            'team_id' => $event->team_id,
351	+            'template' => 'modern',
352	+            'primary_color' => '#112233',
353	+        ]);
354	+
355	+        return [$organiser->fresh(), $team->fresh(), $event->fresh()];
356	+    }
357	+
358	+    private function mintShareLink(User $organiser, Event $event): string
359	+    {
360	+        $response = $this->actingAs($organiser)
361	+            ->postJson(route('events.landing.share', $event));
362	+
363	+        $response->assertSuccessful();
364	+
365	+        $url = $response->json('url');
366	+
367	+        $this->assertIsString($url, 'Minting a share link must return the share url.');
368	+        $this->assertNotSame('', $url);
369	+
370	+        return $url;
371	+    }
372	+
373	+    private function becomeGuest(): void
374	+    {
375	+        $this->app->make('auth')->forgetGuards();
376	+        $this->flushSession();
377	+    }
378	+
379	+    #[Test]
380	+    public function organiser_mints_link_that_serves_unauthenticated_read_only_preview_of_draft_event(): void
381	+    {
382	+        [$organiser, , $event] = $this->organiserWithDraftEvent();
383	+
384	+        $url = $this->mintShareLink($organiser, $event);
385	+        $this->assertStringContainsString($event->uuid, $url, 'The share link must be scoped to one event.');
386	+
387	+        $this->becomeGuest();
388	+
389	+        $response = $this->get($url);
390	+
391	+        $response->assertOk();
392	+        $response->assertSee('data-testid="landing-share-preview"', false);
393	+        $response->assertSeeText($event->title);
394	+        $this->assertSame(EventState::DRAFT, $event->fresh()->state);
395	+    }
396	+
397	+    #[Test]
398	+    public function shared_view_exposes_no_registration_or_authoring_surface_and_does_not_authenticate_the_visitor(): void
399	+    {
400	+        [$organiser, , $event] = $this->organiserWithDraftEvent();
401	+
402	+        $url = $this->mintShareLink($organiser, $event);
403	+
404	+        $this->becomeGuest();
405	+
406	+        $response = $this->get($url);
407	+
408	+        $response->assertOk();
409	+        $response->assertDontSee('data-testid="public-landing-register-form"', false);
410	+        $response->assertDontSee("/webinars/{$event->uuid}/register", false);
411	+        $response->assertDontSee('name="_token"', false);
412	+
413	+        $this->assertGuest();
414	+        $this->get(route('events.landing.edit', $event))->assertRedirect();
415	+    }
416	+
417	+    #[Test]
418	+    public function tampered_share_link_is_refused(): void
419	+    {
420	+        [$organiser, , $event] = $this->organiserWithDraftEvent();
421	+
422	+        $url = $this->mintShareLink($organiser, $event);
423	+
424	+        $this->becomeGuest();
425	+
426	+        $tampered = $url.(str_contains($url, '?') ? '&' : '?').'reviewer=elevated';
427	+
428	+        $this->get($tampered)->assertForbidden();
429	+    }
430	+
431	+    #[Test]
432	+    public function expired_share_link_is_refused(): void
433	+    {
434	+        [$organiser, , $event] = $this->organiserWithDraftEvent();
435	+
436	+        $url = $this->mintShareLink($organiser, $event);
437	+
438	+        $this->becomeGuest();
439	+        $this->travel(1)->years();
440	+
441	+        $this->get($url)->assertForbidden();
442	+    }
443	+
444	+    #[Test]
445	+    public function share_link_for_one_event_does_not_grant_access_to_another_event(): void
446	+    {
447	+        [$organiser, $team, $event] = $this->organiserWithDraftEvent();
448	+
449	+        $otherEvent = Event::factory()
450	+            ->inState(EventState::DRAFT)
451	+            ->for($team)
452	+            ->create([
453	+                'created_by' => $organiser->id,
454	+                'title' => 'Unshared Internal Roadmap Session',
455	+            ]);
456	+        LandingPage::factory()->for($otherEvent)->create(['team_id' => $otherEvent->team_id]);
457	+
458	+        $url = $this->mintShareLink($organiser, $event);
459	+
460	+        $this->becomeGuest();
461	+
462	+        $crossEventUrl = str_replace($event->uuid, $otherEvent->uuid, $url);
463	+        $this->assertNotSame($url, $crossEventUrl);
464	+
465	+        $this->get($crossEventUrl)->assertForbidden();
466	+        $this->get($url)->assertOk()->assertDontSeeText($otherEvent->title);
467	+    }
468	+
469	+    #[Test]
470	+    public function actor_without_event_update_capability_cannot_mint_share_link(): void
471	+    {
472	+        [, $team, $event] = $this->organiserWithDraftEvent();
473	+
474	+        $billingAdmin = User::factory()->create();
475	+        $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
476	+        $billingAdmin->forceFill(['current_team_id' => $team->id])->save();
477	+
478	+        $this->actingAs($billingAdmin->fresh())
479	+            ->postJson(route('events.landing.share', $event))
480	+            ->assertForbidden();
481	+    }
482	+}
